import java.util.Arrays;

public class SearchingTour {
    static int probes;   // how many array elements each search looked at

    static int linearSearch(int[] a, int target) {
        probes = 0;
        for (int i = 0; i < a.length; i++) {
            probes++;
            if (a[i] == target) return i;
        }
        return -1;
    }

    // Invariant: if target is in a, it is inside a[left..right]
    static int binarySearch(int[] a, int target) {
        probes = 0;
        int left = 0, right = a.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;   // avoids int overflow of (left + right)
            probes++;
            if (a[mid] == target) return mid;
            if (a[mid] < target) left = mid + 1;
            else right = mid - 1;
        }
        return -1;
    }

    public static void main(String[] args) {
        // 64 sorted ticket numbers: 3, 10, 17, ..., 444
        int[] tickets = new int[64];
        for (int i = 0; i < tickets.length; i++) tickets[i] = 3 + 7 * i;
        System.out.println("first tickets: " + Arrays.toString(Arrays.copyOf(tickets, 6)) + " ... last " + tickets[63]);

        for (int target : new int[]{10, 290, 444, 100}) {
            int li = linearSearch(tickets, target);
            int linearProbes = probes;
            int bi = binarySearch(tickets, target);
            System.out.printf("find %3d -> linear: index %2d in %2d probes | binary: index %2d in %d probe(s)%n",
                    target, li, linearProbes, bi, probes);
        }
        System.out.println("log2(64) = 6, so binary search never needs more than 7 probes here.");
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;

public class LinearSearch {
    static int comparisons;

    static int indexOf(String[] items, String target) {
        comparisons = 0;
        for (int i = 0; i < items.length; i++) {
            comparisons++;
            if (items[i].equals(target)) return i;   // early exit on the first match
        }
        return -1;                                    // only after checking everything
    }

    static List<Integer> allIndexesOf(String[] items, String target) {
        List<Integer> found = new ArrayList<>();
        for (int i = 0; i < items.length; i++) {
            if (items[i].equals(target)) found.add(i);
        }
        return found;
    }

    static int firstMatch(int[] values, Predicate<Integer> test) {
        for (int i = 0; i < values.length; i++) {
            if (test.test(values[i])) return i;
        }
        return -1;
    }

    public static void main(String[] args) {
        String[] queue = {"Ana", "Bo", "Cy", "Bo", "Dee", "Eli", "Bo", "Fay"};
        for (String name : new String[]{"Bo", "Fay", "Zed"}) {
            int index = indexOf(queue, name);
            System.out.println("indexOf(" + name + ") = " + index + " after " + comparisons + " comparisons");
        }
        System.out.println("every Bo: " + allIndexesOf(queue, "Bo"));

        int[] grades = {78, 91, 64, 55, 88, 49};
        System.out.println("first grade below 60 at index " + firstMatch(grades, g -> g < 60));
        System.out.println("first grade above 95 at index " + firstMatch(grades, g -> g > 95));
    }
}

