public class BinarySearch {
    static int search(int[] a, int target) {
        int left = 0, right = a.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            System.out.println("  range [" + left + ", " + right + "] mid=" + mid + " a[mid]=" + a[mid]);
            if (a[mid] == target) return mid;
            if (a[mid] < target) left = mid + 1;   // target can only be to the right
            else right = mid - 1;                  // target can only be to the left
        }
        return -1;
    }

    // First index with a[i] >= target (half-open range [left, right))
    static int lowerBound(int[] a, int target) {
        int left = 0, right = a.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (a[mid] < target) left = mid + 1;
            else right = mid;
        }
        return left;
    }

    // First index with a[i] > target
    static int upperBound(int[] a, int target) {
        int left = 0, right = a.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (a[mid] <= target) left = mid + 1;
            else right = mid;
        }
        return left;
    }

    public static void main(String[] args) {
        int[] a = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};
        System.out.println("search 23:");
        System.out.println("  -> index " + search(a, 23));
        System.out.println("search 40:");
        System.out.println("  -> index " + search(a, 40));

        int[] scores = {10, 20, 30, 30, 30, 30, 40, 50};
        int first = lowerBound(scores, 30);
        int afterLast = upperBound(scores, 30);
        System.out.println("plain search for 30 lands on index " + searchQuiet(scores, 30));
        System.out.println("first 30 at " + first + ", last 30 at " + (afterLast - 1) + ", count " + (afterLast - first));
        System.out.println("insertion point for 35: " + lowerBound(scores, 35));
    }

    static int searchQuiet(int[] a, int target) {
        int left = 0, right = a.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (a[mid] == target) return mid;
            if (a[mid] < target) left = mid + 1;
            else right = mid - 1;
        }
        return -1;
    }
}

