public class InterpolationSearch {
    static int probes;

    static int interpolation(int[] a, int target, boolean trace) {
        probes = 0;
        int lo = 0, hi = a.length - 1;
        while (lo <= hi && target >= a[lo] && target <= a[hi]) {
            int pos;
            if (a[hi] == a[lo]) pos = lo;   // avoid dividing by zero
            else pos = lo + (int) ((long) (target - a[lo]) * (hi - lo) / (a[hi] - a[lo]));
            probes++;
            if (trace) System.out.println("  probe index " + pos + " (value " + a[pos] + ")");
            if (a[pos] == target) return pos;
            if (a[pos] < target) lo = pos + 1;
            else hi = pos - 1;
        }
        return -1;
    }

    static int binary(int[] a, int target) {
        probes = 0;
        int lo = 0, hi = a.length - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            probes++;
            if (a[mid] == target) return mid;
            if (a[mid] < target) lo = mid + 1;
            else hi = mid - 1;
        }
        return -1;
    }

    public static void main(String[] args) {
        int[] even = new int[100];
        int[] squares = new int[100];
        for (int i = 0; i < 100; i++) {
            even[i] = 10 * i;          // 0, 10, 20, ... evenly spaced
            squares[i] = i * i;        // 0, 1, 4, 9, ... gaps keep growing
        }
        System.out.println("evenly spaced, find 730:");
        int idx = interpolation(even, 730, true);
        System.out.println("  interpolation: index " + idx + " in " + probes + " probe(s)");
        binary(even, 730);
        System.out.println("  binary search: " + probes + " probes");

        System.out.println("squares, find 81 (= 9 * 9):");
        idx = interpolation(squares, 81, false);
        System.out.println("  interpolation: index " + idx + " in " + probes + " probe(s)");
        binary(squares, 81);
        System.out.println("  binary search: " + probes + " probes");
    }
}

import java.util.Arrays;

public class ExponentialSearch {
    static int exponentialSearch(int[] a, int target) {
        if (a.length == 0) return -1;
        if (a[0] == target) return 0;
        int bound = 1;
        while (bound < a.length && a[bound] < target) {
            System.out.println("  a[" + bound + "] = " + a[bound] + " < " + target + ", double the bound");
            bound *= 2;
        }
        int lo = bound / 2;
        int hi = Math.min(bound, a.length - 1);   // never read past the end
        System.out.println("  binary search in [" + lo + ", " + hi + "]");
        int result = Arrays.binarySearch(a, lo, hi + 1, target);   // 'to' is exclusive
        return result >= 0 ? result : -1;
    }

    public static void main(String[] args) {
        int[] a = new int[40];
        for (int i = 0; i < a.length; i++) a[i] = 6 * i + 6;   // 6, 12, 18, ..., 240
        System.out.println("array: 6, 12, 18, ..., " + a[a.length - 1] + " (" + a.length + " values)");
        for (int target : new int[]{18, 70, 72, 234}) {
            System.out.println("find " + target + ":");
            System.out.println("  -> index " + exponentialSearch(a, target));
        }
    }
}

public class SearchComparison {
    static int probes;

    static int linear(int[] a, int t) {
        for (int i = 0; i < a.length; i++) { probes++; if (a[i] == t) return i; }
        return -1;
    }

    static int binary(int[] a, int t, int lo, int hi) {
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            probes++;
            if (a[mid] == t) return mid;
            if (a[mid] < t) lo = mid + 1; else hi = mid - 1;
        }
        return -1;
    }

    static int interpolation(int[] a, int t) {
        int lo = 0, hi = a.length - 1;
        while (lo <= hi && t >= a[lo] && t <= a[hi]) {
            int pos = a[hi] == a[lo] ? lo : lo + (int) ((long) (t - a[lo]) * (hi - lo) / (a[hi] - a[lo]));
            probes++;
            if (a[pos] == t) return pos;
            if (a[pos] < t) lo = pos + 1; else hi = pos - 1;
        }
        return -1;
    }

    static int exponential(int[] a, int t) {
        probes++;
        if (a[0] == t) return 0;
        int bound = 1;
        while (bound < a.length) {
            probes++;
            if (a[bound] >= t) break;
            bound *= 2;
        }
        return binary(a, t, bound / 2, Math.min(bound, a.length - 1));
    }

    public static void main(String[] args) {
        int[] a = new int[1000];
        for (int i = 0; i < a.length; i++) a[i] = 5 * i + 1;      // 1, 6, 11, ..., 4996
        System.out.println(String.format("%-8s %6s %7s %7s %14s %12s", "target", "index", "linear", "binary", "interpolation", "exponential"));
        for (int t : new int[]{16, 2501, 4996, 2502}) {
            int[] counts = new int[4];
            int index = -1;
            for (int s = 0; s < 4; s++) {
                probes = 0;
                index = switch (s) {
                    case 0 -> linear(a, t);
                    case 1 -> binary(a, t, 0, a.length - 1);
                    case 2 -> interpolation(a, t);
                    default -> exponential(a, t);
                };
                counts[s] = probes;
            }
            System.out.println(String.format("%-8d %6d %7d %7d %14d %12d", t, index, counts[0], counts[1], counts[2], counts[3]));
        }
    }
}

