probes = 0


def linear(a, t):
    global probes
    for i, value in enumerate(a):
        probes += 1
        if value == t:
            return i
    return -1


def binary(a, t, lo, hi):
    global probes
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        probes += 1
        if a[mid] == t:
            return mid
        if a[mid] < t:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


def interpolation(a, t):
    global probes
    lo, hi = 0, len(a) - 1
    while lo <= hi and a[lo] <= t <= a[hi]:
        pos = lo if a[hi] == a[lo] else lo + (t - a[lo]) * (hi - lo) // (a[hi] - a[lo])
        probes += 1
        if a[pos] == t:
            return pos
        if a[pos] < t:
            lo = pos + 1
        else:
            hi = pos - 1
    return -1


def exponential(a, t):
    global probes
    probes += 1
    if a[0] == t:
        return 0
    bound = 1
    while bound < len(a):
        probes += 1
        if a[bound] >= t:
            break
        bound *= 2
    return binary(a, t, bound // 2, min(bound, len(a) - 1))


